import mq3.botlib.l_memory as m
function main(args) s=m.create(123456,true);a=m.GetMemory(s,10,true);print("heap|"+str(m.MemoryByteSize(s,a,true))+"|"+str(s.allocatedmemory)+"|"+str(s.totalmemorysize)+"|"+str(s.numblocks));b=m.GetClearedHunkMemory(s,5,true);data=m.readBytes(s,b,0,1,true);print("hunk|"+str(m.MemoryByteSize(s,b,true))+"|"+str(s.allocatedmemory)+"|"+str(s.totalmemorysize)+"|"+str(s.numblocks)+"|"+str(data[0]));print("available|"+str(m.AvailableMemory(s)));m.FreeMemory(s,a,true);print("freeheap|"+str(s.allocatedmemory)+"|"+str(s.totalmemorysize)+"|"+str(s.numblocks));m.FreeMemory(s,b,true);print("freehunk|"+str(s.allocatedmemory)+"|"+str(s.totalmemorysize)+"|"+str(s.numblocks));c=m.GetMemory(s,3,true);m.DumpMemory(s,true);print("dump|"+str(s.allocatedmemory)+"|"+str(s.totalmemorysize)+"|"+str(s.numblocks));return 0 end function
